function UICultivateEquipDiySuitEditDialog:FixUiStateParams(uiStateParams)
    local equipIdList = uiStateParams.equipIdList
    for i, v in ipairs(equipIdList) do
        if checkNumber(v) then
            equipIdList[i] = equipComp:GetEquipById(v) and v or 0
        end
    end
    local playerEquipmentCoreId = checkNumber(uiStateParams.playerEquipmentCoreId)
    if playerEquipmentCoreId > 0 then
        uiStateParams.playerEquipmentCoreId = equipComp:GetEquipCoreById(playerEquipmentCoreId) and playerEquipmentCoreId or 0
    end
end

