function UICultivateEquipDiySuitEditDialog:RefreshUI(isInit)
    local suitData = self:GetSuitData()
    self.Placeholder.text = string.isEmpty(suitData.name) and localize("请输入名称") or suitData.name
    local equipIdList = self:GetEquipIdList()
    local playerEquipmentCoreId = self.playerEquipmentCoreId
    self:RefreshEquipBackpack(equipIdList, playerEquipmentCoreId)
    if not isInit then
        self:RefreshEquipNodeGroup(equipIdList, playerEquipmentCoreId, true)
    end
    self:RefreshSuitDescAndAttrNode(equipIdList, playerEquipmentCoreId)
end

function UICultivateEquipDiySuitEditDialog:RefreshEquipBackpack(equipIdList, playerEquipmentCoreId)
    ---@type UICultivateEquipBackpackNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.EquipBackpackNode, UICultivateEquipBackpackNodeMBPath)
    if mbEnv == nil then return end
    if self.isBackpackInit then
        self.isBackpackInit = nil
        mbEnv:InitData(equipIdList, self.part, playerEquipmentCoreId, self.career)
        mbEnv:InitTabGroupIndex()
        mbEnv:SetClickCellAction(Bind(self, self.OnCellClickAction))
        mbEnv:SetUpdatePartAction(Bind(self, self.OnUpdatePartAction))
    end

    local parameters = self.controller.Argument.parameters
    local uiStateParams = parameters.uiStateParams
    if uiStateParams then
        mbEnv:RecoveryUIState(uiStateParams)
        self.controller.Argument.parameters.uiStateParams = nil
    end
    mbEnv:RefreshUI("UICultivateEquipDiySuitEditDialog")
    --mbEnv:Set
end

