function UICultivateEquipDiySuitEditDialog:SaveUIState()
    ---@type UICultivateEquipBackpackNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.EquipBackpackNode, UICultivateEquipBackpackNodeMBPath)
    if mbEnv == nil then return end
    local backpackCacheData = mbEnv:SaveUIState()
    local parameters = self.controller.Argument.parameters or {}
    local uiStateParams = {
        part                  = self.part,
        equipIdList           = self:GetEquipIdList(),
        playerEquipmentCoreId = self.playerEquipmentCoreId,
    }
    table.merge(uiStateParams, backpackCacheData)
    parameters.uiStateParams = uiStateParams
    self.controller.Argument.parameters = parameters
end

function UICultivateEquipDiySuitEditDialog:CloseAllDialog()
    cs_coroutine.start(function()
        ---@type UICultivateEquipBackpackNodeMB
        local mbEnv = CfUtils.GetLuaScr(self.EquipBackpackNode, UICultivateEquipBackpackNodeMBPath)
        if mbEnv:GetFilterType() == FilTerType.NORMAL_SELECT_SUIT then
            cs_coroutine.yield_return(UIModule.BackDialog())
        end
        cs_coroutine.yield_return(UIModule.BackDialog())
    end)
end

function UICultivateEquipDiySuitEditDialog:SwitchPart(part, isUpdateBackpack)
    if self.part == part then return end

    ---@type UICultivateEquipAndCoreGroupNode
    local equipNodeGroupMB = CfUtils.GetLuaScr(self.EquipNodeGroup.gameObject, UICultivateEquipNodeGroupNodePath)
    if equipNodeGroupMB then
        equipNodeGroupMB:RefreshSelectStateByPart(self.part, false)
        equipNodeGroupMB:RefreshSelectStateByPart(part, true)
    end

    self.part = part

    if isUpdateBackpack then
        self:SwitchBackpackPart(part)
    end
end

