function UICultivateEquipDiySuitEditDialog:OnEventOperateEquipOrCore(params, equipType, direction)
    local isLeft = direction == 1
    local status = params.status
    local dojo = params.dojo
    local part = params.part

    if isLeft then
        self:EnterCultivateEquipDialog(dojo.id)
    else
        local t = {
            [Status.CultivateAndInstall] = Status.Install,
            [Status.CultivateAndReplace] = Status.Replace,
            [Status.CultivateAndUninstall] = Status.Uninstall,
        }
        local realStatus = t[status] or status
        self:UpdateCardOnEquipOrCore(dojo, equipType, part, realStatus)
    end

end

function UICultivateEquipDiySuitEditDialog:EnterCultivateEquipDialog(playerEquipId)
    self:SaveUIState()
    EquipUtils.EnterCultivateEquipDialog(playerEquipId, {
        { id = Constants.UITypeIds.UICultivateEquipDiySuitDialog },
        { id = Constants.UITypeIds.UICultivateEquipDiySuitEditDialog },
    })
end

function UICultivateEquipDiySuitEditDialog:UpdateCardOnEquipOrCore(dojo, equipType, part, status)
    local isUninstall = status == Status.Uninstall
    local isEquip     = equipType == EquipType.Equip
    local id          = checkNumber(dojo.id)
    local backpackNewId, backpackOldId = self:GetBackpackNewIdAndOldIdByStatus(status, id, part, isEquip)
    local equipmentCoreDojo
    if isEquip then
        local equipId = isUninstall and 0 or id
        self.equipIdList[part] = equipId

        equipmentCoreDojo = equipComp:GetEquipCoreById(self.playerEquipmentCoreId)
    else
        self.playerEquipmentCoreId = isUninstall and 0 or id
        equipmentCoreDojo = equipComp:GetEquipCoreById(id)
    end

    --- 更新装备背包
    self:RefreshBackpackDataAndRefreshList(checkInt(backpackNewId), checkInt(backpackOldId), part)

    self:RefreshEquipNodeGroupByPart(part, dojo, equipmentCoreDojo, isUninstall)

    self:RefreshSuitDescAndAttrNode(self.equipIdList, self.playerEquipmentCoreId)
end


function UICultivateEquipDiySuitEditDialog:GetBackpackNewIdAndOldIdByStatus(status, id, part, isEquip)
    local backpackNewId, backpackOldId = 0, 0
    --- 卸载 backpackNewId = id, backpackOldId = 0
    --- 安装 backpackNewId = 0, backpackOldId = id
    --- 替换 backpackNewId = 卡牌身上的装备或核心id, backpackOldId = id

    if status == Status.Install then
        backpackOldId = id
    elseif status == Status.Uninstall then
        backpackNewId = id
    elseif status == Status.Replace then
        backpackNewId = isEquip and self.equipIdList[part] or self.playerEquipmentCoreId
        backpackOldId = id
    end
    return backpackNewId, backpackOldId

end

