function UICultivateEquipDiySuitEditDialog:OnCellClickAction(backpackDataId, part, equipType)
    if backpackDataId <= 0 then return end
    local curDojo, compareDojo
    local equipPart
    if equipType == EquipType.Core then
        curDojo = equipComp:GetEquipCoreById(self.playerEquipmentCoreId)
        compareDojo = equipComp:GetEquipCoreById(backpackDataId)
        equipPart = -1
    elseif equipType == EquipType.Equip then
        local equipIdList = self:GetEquipIdList()
        equipPart = part or self.part
        curDojo = equipComp:GetEquipById(equipIdList[equipPart])
        compareDojo = equipComp:GetEquipById(backpackDataId)

    end

    self:LoadComparedView(curDojo, compareDojo, equipType, equipPart, function()
        ---@type UICultivateEquipBackpackNodeMB
        local mbEnv = CfUtils.GetLuaScr(self.EquipBackpackNode, UICultivateEquipBackpackNodeMBPath)
        if mbEnv == nil then return end
        mbEnv:HideSelectIndex()
    end)
end

function UICultivateEquipDiySuitEditDialog:OnUpdatePartAction(part)
    self:SwitchPart(part)
end

function UICultivateEquipDiySuitEditDialog:OnClickEquipNodeGroupAction(part)
    self:SwitchPart(part, true)

    local curDojo, equipType
    if part == -1 then
        local playerEquipmentCoreId = self.playerEquipmentCoreId
        curDojo = equipComp:GetEquipCoreById(playerEquipmentCoreId)
        equipType = EquipType.Core
    else
        curDojo = equipComp:GetEquipById(self:GetEquipIdList()[part])
        equipType = EquipType.Equip
    end
    if curDojo and self.part ~= 0 then
        self:LoadComparedView(curDojo, nil, equipType, part)
    end
end

function UICultivateEquipDiySuitEditDialog:OnClickDetermineBtnAction()
    local text = self.InputField.text
    local suitData = self:GetSuitData()
    text = string.isEmpty(text) and suitData.name or text
    if not Constants.MODULE_SWITCH.Is_Read_Only then
        if string.isEmpty(text) then
            GameUtils.Toast(localize('自定义套装名称不能为空'))
            return
        
        end
    end

    local argument    = self.controller.Argument.parameters
    local suitId      = argument.newSuitId
    local equipIdList = self:GetEquipIdList()
    local playerEquipmentCoreId = self.playerEquipmentCoreId
    if not EquipUtils.CheckIsInstallEquip(equipIdList) and playerEquipmentCoreId <= 0 then
        GameUtils.Toast(localize('自定义套装装备不能为空'))
        return
    end

    local isEdit      = argument.isEdit
    local equipments  = table.concat(equipIdList, ',')
    local name = Constants.MODULE_SWITCH.Is_Read_Only and suitId or text
    GameUtils.Request(Interfaces.EquipmentSaveDiySuit, {
        suitId = suitId,
        name = name,
        isNew = isEdit and 0 or 1,
        playerEquipmentCoreId = playerEquipmentCoreId,
        equipments = equipments},
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    GameUtils.Toast(isEdit and localize("套装编辑成功") or localize("套装保存成功"))
                    if isEdit then
                        equipComp:UpdateDiySuitBySuitId(suitId, name, equipments, playerEquipmentCoreId)
                    else
                        equipComp:AddDiySuitBySuitId(suitId, name, equipments, playerEquipmentCoreId)
                    end
                    self:CloseAllDialog()
                end
            end)

end

